#include <iostream>
class ErrorCategory {
public:
    int id;
    ErrorCategory(int id) : id(id) {}
    bool operator!=(const ErrorCategory& rhs) const noexcept {
        return this->id != rhs.id;
    }
};
int main() {
    ErrorCategory error1(1);
    ErrorCategory error2(2);
    if (error1 != error2) {
        std::cout << "Errors are different." << std::endl;
    }
    return 0;
}
